-- Garrison addon: shared namespace, state and helpers. Load order is in the .toc; modules talk to each other only through the table G.
--   Catalog.lua  generated by tools/gen_garrison_catalog.py (never edit)     Preview.lua  3D preview + its view math
--   Placed.lua   "Placed" tab: nudge pad, pick marker                         List.lua     category buttons, item list, selection, buttons
--   Frame.lua    main window, server messages, /garrison
-- Server side: scripts/garrison.lua (module "house").
WotlkGarrison = WotlkGarrison or {}
AcoreLib.Announce("garrison")   -- tells the server this client has the addon (the portal refuses players without it)
local G = WotlkGarrison
local C = WotlkGarrisonCatalog
G.C = C
for _, e in ipairs(C.items) do if e.hid == 1 then e.hidden = true end end   -- categories Removed + Unsorted: hidden from players (the admin tool, if loaded, can show them to a GM character)

G.ROW_H, G.ROW_N = 26, 14
-- UI state. tab = "npcs" | "objects" | "placed"; selected = a catalog entry (or a placed-list entry on the Placed tab)
G.st = {
    tab = C.tabs[1].key, cat = C.tabs[1].cats[1], selected = nil,
    inHome = false, primed = false,
    placed = {},                  -- kinds placed (single-instance)
    decor = {}, decorCount = {},  -- { {did, kind}, ... } in server order / count per kind
    wantSelect = nil,             -- decor id to select once the (chunked) list has arrived
    selDid = nil, previewedDid = nil,
    currency = "free", currencyItem = 0,   -- from the server: what placing costs (acore_settings.garrison.currency)
}
G.ui = {}   -- widgets, filled by the Build* functions

-- price of placing e, as text for the Place button: "" when free
function G.PriceText(e)
    local st = G.st
    if st.currency == "free" or not e or (e.price or 0) <= 0 then return "" end
    if st.currency == "gold" then return " - " .. e.price .. " gold" end
    local name = GetItemInfo(st.currencyItem)
    return " - " .. e.price .. " x " .. (name or ("item " .. st.currencyItem))
end

-- Subcategories (one level): a category named "Holiday > Winter Veil" is the child "Winter Veil" of the parent "Holiday". Nothing else in the
-- catalog, the saved admin data or the server knows about it: it is only a naming convention that the category column groups on.
function G.SplitCat(name)
    local parent, child = name:match("^(.-) > (.+)$")
    if parent and parent ~= "" then return parent, child end
    return name, nil
end

-- Rows of the category column. names = the visible category names in order, open = { [parent] = true } for expanded parents.
-- A parent with children is a toggle row ("+ Holiday" / "- Holiday") that selects its own items too when there are any ("Holiday" itself).
-- Row fields: label, cat (the category this row selects), parent (set on a toggle row), indent (a child row).
function G.CategoryRows(names, open)
    local groups, order = {}, {}
    for _, name in ipairs(names) do
        local p, c = G.SplitCat(name)
        local g = groups[p]
        if not g then g = { kids = {} }; groups[p] = g; order[#order + 1] = p end
        if c then g.kids[#g.kids + 1] = { cat = name, label = c } else g.direct = name end
    end
    local rows = {}
    for _, p in ipairs(order) do
        local g = groups[p]
        if #g.kids == 0 then
            rows[#rows + 1] = { label = p, cat = g.direct }
        else
            rows[#rows + 1] = { label = (open[p] and "- " or "+ ") .. p, parent = p, cat = g.direct or g.kids[1].cat }
            if open[p] then for _, k in ipairs(g.kids) do rows[#rows + 1] = { label = k.label, cat = k.cat, indent = true } end end
        end
    end
    return rows
end

function G.Request() AcoreLib.Send("house", "list", "") end
function G.TabDef(key) for _, t in ipairs(C.tabs) do if t.key == key then return t end end end
function G.ItemByKind(kind) for _, e in ipairs(C.items) do if e.kind == kind then return e end end end

-- one-shot message under the window (fades after 3 s) and the two-click confirm on "Remove all decor"
local msgUntil, clearUntil = 0, 0
function G.SetMsg(text, r, g, b)
    local m = G.ui.msgText
    if m then m:SetText(text or ""); m:SetTextColor(r or 1, g or 1, b or 1); msgUntil = GetTime() + 3 end
end
function G.ArmClear(on)   -- true = start the 3 s confirm window; false = disarm. Returns whether it WAS armed
    local was = clearUntil > 0
    clearUntil = on and (GetTime() + 3) or 0
    return was
end
local timer = CreateFrame("Frame")
timer:SetScript("OnUpdate", function()
    local t = GetTime()
    if msgUntil > 0 and t > msgUntil then msgUntil = 0; if G.ui.msgText then G.ui.msgText:SetText("") end end
    if clearUntil > 0 and t > clearUntil then clearUntil = 0; if G.ui.clearBtn then G.ui.clearBtn:SetText("Remove all decor") end end
end)
